function GUICustomDialog:setDefault()
    self.customParams = nil
    self.leftClickListener = nil
    self.rightClickListener = nil
    self.closeClickListener = nil
    self.hideListener = nil
    self.llPanel:SetWidth(self.panelWidth)
    self.llPanel:SetHeight(self.panelHeight)
    self.tvTitleText:SetText(Lang:getString("gui_dialog_tip_title_tip"))
    self.btnClose:SetVisible(true)
    self.llContent:SetHeight(self.contentHeight)
    self.lvContentText:SetVisible(false)
    self.lvContentText:SetScrollOffset(0)

    self.tvContentText:SetVisible(true)
    self.tvContentText:SetText("")
    self.ivExtraIcon:SetVisible(false)
    self.ivExtraIcon:SetHexagonImage("", "")
    self.ivExtraIcon:SetRenderAsBlock(false)

    self.ivLeftIcon:SetVisible(false)
    self.ivLeftIcon:SetWidth(self.leftIconWidth)
    self.ivLeftIcon:SetHeight(self.leftIconHeight)
    self:setLeftText(Lang:getString("gui_dialog_tip_btn_cancel"))
    self:setLeftDisable(true)
    self:setRightDisable(true)

    self.ivRightIcon:SetVisible(false)
    self.ivRightIcon:SetWidth(self.rightIconWidth)
    self.ivRightIcon:SetHeight(self.rightIconHeight)
    self:setRightText(Lang:getString("gui_dialog_tip_btn_sure"))
    self:setRightDisable(true)

    self.tvContentText:SetTextHorzAlign(HorizontalAlignment.Center)
    self.tvContentText:SetTextVertAlign(VerticalAlignment.Center)
    self.tvScrollText:SetTextHorzAlign(HorizontalAlignment.Center)
    self.tvScrollText:SetTextVertAlign(VerticalAlignment.Top)

    self.disableTime = 0
    if self.contentView ~= nil then
        self.contentView:hide()
        self.contentView = nil
    end
    if self.hideTimer then
        LuaTimer:cancel(self.hideTimer)
    end
    if self.disableTimer then
        LuaTimer:cancel(self.disableTimer)
    end

    if self.btnNoShowTip then
        self.btnNoShowTip:SetVisible(false)
    end
    if self.noShowTipFunc then
        self.noShowTipFunc(self.noShowTipStatus)
        self.noShowTipFunc = nil
    end
end

