end

function GUICustomDialog:setNoShowTipBtnStatus(status)
    self.noShowTipStatus = status
    if self.btnNoShowTip then
        self.btnNoShowTip:SetNormalImage(status and "set:bed_war_3_setting.json image:img_0_selected04" or "set:bed_war_3_setting.json image:img_0_selected03")
        self.btnNoShowTip:SetPushedImage(status and "set:bed_war_3_setting.json image:img_0_selected04" or "set:bed_war_3_setting.json image:img_0_selected03")
    end
end

