---设置对话框额外信息图片和文字(默认不可见)
---@param image string 图片名称
---@param text string 文字多语言或文字
function CustomDialog.setExtraInfo(image, text)
    dialog.ivExtraIcon:SetVisible(true)
    dialog.ivExtraIcon:SetImage(image)
    dialog.tvExtraText:SetText(Lang:getString(text))
    if #tostring(text) == 0 then
        dialog.ivExtraIcon:SetXPosition({ 0, 0 })
    else
        local offset = #tostring(image) == 0 and dialog.ivExtraIcon:GetPixelSize().x or 0
        local textWidth = dialog.tvExtraText:GetFont():GetTextExtent(text, 1)
        dialog.ivExtraIcon:SetXPosition({ 0, -(textWidth + 8) / 2 - offset })
    end
    return CustomDialog
end

function CustomDialog.setCurrencyInfo(currency, price)
    dialog.ivExtraIcon:SetVisible(true)
    if type(currency) == "number" then
        dialog.ivExtraIcon:SetImage(PayHelper.getMoneyIcon(currency))
    else
        GuiItemStack.showItemIcon(dialog.ivExtraIcon, currency[1], currency[2], "")
    end
    dialog.tvExtraText:SetText(price)
    if #tostring(price) == 0 then
        dialog.ivExtraIcon:SetXPosition({ 0, 0 })
    else
        local textWidth = dialog.tvExtraText:GetFont():GetTextExtent(tostring(price), 1)
        dialog.ivExtraIcon:SetXPosition({ 0, -(textWidth + 8) / 2 })
    end
    return CustomDialog
end

